SELECT sku, count(DISTINCT (revenue_inr/NULLIF(units_sold,0))) AS distinct_prices,
       min(revenue_inr/NULLIF(units_sold,0)) AS min_p, max(revenue_inr/NULLIF(units_sold,0)) AS max_p
FROM store.daily_sales GROUP BY sku ORDER BY sku;

SELECT sku, sum(units) units, sum(CASE WHEN reason='expired' THEN units ELSE 0 END) expired_units,
       sum(CASE WHEN reason='damaged' THEN units ELSE 0 END) damaged_units, count(*) rows
FROM store.write_offs GROUP BY sku ORDER BY sku;

SELECT sku, sum(book_on_hand_close) total_book, min(book_on_hand_close) mn, max(book_on_hand_close) mx,
       avg(book_on_hand_close)::numeric(10,2) avg_book
FROM store.inventory_book GROUP BY sku ORDER BY sku;

SELECT date(bill_ts) d, count(DISTINCT bill_id) bills, count(*) lines,
       count(DISTINCT right(bill_id,6)) seqs
FROM store.pos_lines GROUP BY 1 ORDER BY 1 LIMIT 10;

SELECT sku, gtin, name, pack, case_units, case_kg, flow, dc_slot, price_inr, cost_inr
FROM store.products
ORDER BY sku;

SELECT table_schema, table_name FROM information_schema.tables
WHERE table_schema NOT IN ('pg_catalog','information_schema')
ORDER BY table_schema, table_name;

SELECT tender, till_status, note, count(*), sum(amount_inr)
FROM payments.pos_payments
GROUP BY 1,2,3 ORDER BY 1,2,4 DESC;

SELECT tender, till_status, count(*) n, min(ts)::text mn, max(ts)::text mx
FROM payments.pos_payments
GROUP BY 1,2 ORDER BY 1,2;

WITH june_bills AS (
  SELECT DISTINCT bill_id FROM store.pos_lines WHERE bill_ts >= '2026-06-01' AND bill_ts < '2026-07-01'
)
SELECT p.tender, p.till_status, count(*) n, count(DISTINCT p.bill_id) bills
FROM june_bills b JOIN payments.pos_payments p ON p.bill_id=b.bill_id
GROUP BY 1,2 ORDER BY 1,2;

SELECT min(bill_ts) AS min_ts, max(bill_ts) AS max_ts, count(DISTINCT bill_id) AS bills, count(*) AS lines,
       count(DISTINCT sku_scanned) AS skus, count(DISTINCT gtin_scanned) AS gtins
FROM store.pos_lines;

SELECT reason, count(*) AS lines, sum(units) AS units FROM store.write_offs
WHERE date >= DATE '2026-06-01' AND date < DATE '2026-07-01'
GROUP BY reason ORDER BY reason;

SELECT trigger, count(*) AS n, sum(counted - book_before) AS net_units, sum(abs(adjustment)) AS abs_adj
FROM store.stock_counts
GROUP BY trigger ORDER BY trigger;

SELECT 'products' AS t, sku, name, pack, flow, dc_slot, price_inr::text, cost_inr::text, case_units::text, case_kg::text FROM store.products
UNION ALL
SELECT 'pos_payments', bill_id, tender, till_status, note, attempt::text, amount_inr::text, rrn, NULL, NULL FROM payments.pos_payments LIMIT 0;

